SELECT (DATE_TRUNC('DAY', "USAGE_DAY")) AS "TIME_BUCKET", SUM(CASE WHEN USAGE_TYPE = 'data transfer' THEN SPEND_IN_CURRENCY ELSE 0 END) AS "ORG_EGRESS_COST" FROM (SELECT "ACCOUNT_NAME" AS ACCOUNT_NAME, "ORGANIZATION_NAME" AS ORGANIZATION_NAME, CAST("USAGE_DATE" AS DATE) AS USAGE_DAY, "USAGE_TYPE" AS USAGE_TYPE, "CURRENCY" AS CURRENCY, (CAST("USAGE" AS DECIMAL(38, 9))) AS USAGE_UNITS, (CAST("USAGE_IN_CURRENCY" AS DECIMAL(38, 9))) AS SPEND_IN_CURRENCY FROM usage_in_currency_daily) AS base GROUP BY (DATE_TRUNC('DAY', "USAGE_DAY")) ORDER BY "ORG_EGRESS_COST" DESC, "TIME_BUCKET" LIMIT 100
